                montantDecalage = MontantChiffreAffaire0101 / 30;

                if (janvier > delaiClient)
                {
                    decalage01 = janvier - delaiClient;
                    decalage02 = 30 - decalage01;

                    EncaissementsRecuClients0101 = montantDecalage * decalage01;
                    EncaissementsRecuClients0201 = montantDecalage * decalage02;

                }
                else
                {
                    if (fevrier > delaiClient)
                    {
                        decalage01 = fevrier - delaiClient;
                        decalage02 = 30 - decalage01;

                        EncaissementsRecuClients0201 = montantDecalage * decalage01;
                        EncaissementsRecuClients0301 = montantDecalage * decalage02;

